message:
Running command: set -euo pipefail;
cat &gt;/usr/local/bin/docker-weekly-cleanup.sh &lt;&lt;'EOF'
#!/bin/sh
set -eu
if ! command -v docker >/dev/null 2>&1; then
  echo "$(date -Is) docker not found; skipping cleanup" >&2
  exit 0
fi
docker system prune -af --volumes || true
docker builder prune -af || true
docker image prune -af || true
docker volume prune -f || true
docker container prune -f || true
docker network prune -f || true
EOF
chmod 755 /usr/local/bin/docker-weekly-cleanup.sh;
cat &gt;/etc/cron.d/docker-prune &lt;&lt;'EOF'
# Clean up Docker disk usage weekly at 03:30 on Sundays
SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
30 3 * * 0 root /usr/local/bin/docker-weekly-cleanup.sh >>/var/log/docker-prune.log 2>&1
EOF
chmod 644 /etc/cron.d/docker-prune;
touch /var/log/docker-prune.log;
ls -l /usr/local/bin/docker-weekly-cleanup.sh /etc/cron.d/docker-prune /var/log/docker-prune.log;
echo "===== /etc/cron.d/docker-prune =====";
sed -n '1,120p' /etc/cron.d/docker-prune;
echo "===== /usr/local/bin/docker-weekly-cleanup.sh =====";
sed -n '1,200p' /usr/local/bin/docker-weekly-cleanup.sh

